#[path="../../research/sources/backend/tip_compile_module.rs"] mod original;
fn main(){let t=original::Vm::new().unwrap();let mut n=0;for (start,want) in [(0x0fac03d5,vec![0x17]),(0x0fac039d,vec![0x17,0x1234]),(0x0fb3484c,vec![0x11,0x17,0x1357]),(0x0fb348ac,vec![0x11,0x19,0x23,0x1357])]{let mut v=t.clone();v.memory.map(0x70000000,vec![0;0x10000]).unwrap();let sp=0x70008000;v.set_register("ESP",sp as u128).unwrap();v.set_register("ESI",0x70001000).unwrap();v.set_register("EDI",0x70002000).unwrap();v.set_register("EBP",0x23).unwrap();v.memory.write_u32(0x70001000,0x70003000).unwrap();v.memory.write_u32(0x70002000+0x1c,0x17).unwrap();v.memory.write_u32(0x70002000+0x24,0x5678).unwrap();v.memory.write_u32(sp+0x4c,0x11).unwrap();v.memory.write_u32(sp+0x10,0x19).unwrap();v.memory.write_u32(sp+0x1c,0xabcd1357).unwrap();v.pc=start;let mut words=vec![];for _ in 0..100{if v.pc==0x0fac03f0{break;}if v.pc==0x0fac2e29{assert_eq!(v.stack_argument(0).unwrap(),0x5678);v.return_stdcall(0x1234,4).unwrap();}else if v.pc==0x0fac0b2e {words.push(v.stack_argument(0).unwrap() as u16);v.return_stdcall(0,4).unwrap();}else{v.step(&mut original::NoHost).unwrap();}}assert_eq!(words,want,"entry={start:x}");n+=1;}println!("{n} original tail branch-frame fixtures passed; helper FAC2E29 returns1234");}
